CREATE OR REPLACE FUNCTION docworks_private.limites(p_inmobiliaria_id uuid, p_limite_usuarios integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare anterior integer; usados integer;
begin
 perform docworks_private.exigir_super();
 if p_limite_usuarios<0 or p_limite_usuarios>10000 then raise exception 'Límite inválido'; end if;
 perform 1 from public.inmobiliarias where id=p_inmobiliaria_id for update;
 if not found then raise exception 'Inmobiliaria inexistente'; end if;
 usados:=public.fn_usuarios_activos_count(p_inmobiliaria_id)+public.fn_invitaciones_pendientes_count(p_inmobiliaria_id);
 if coalesce(p_limite_usuarios,(select pl.limite_usuarios from public.membresias m join public.planes pl on pl.id=m.plan_id where m.inmobiliaria_id=p_inmobiliaria_id))<usados then
  raise exception 'El límite no puede ser menor que los usuarios activos e invitaciones pendientes';
 end if;
 select limite_usuarios into anterior from docworks_private.seguimiento where inmobiliaria_id=p_inmobiliaria_id;
 insert into docworks_private.seguimiento(inmobiliaria_id,limite_usuarios) values(p_inmobiliaria_id,p_limite_usuarios)
 on conflict(inmobiliaria_id) do update set limite_usuarios=excluded.limite_usuarios,actualizado_en=now();
 insert into docworks_private.eventos(actor,inmobiliaria_id,accion,anterior,nuevo)
 values(auth.uid(),p_inmobiliaria_id,'limite_usuarios',to_jsonb(anterior),to_jsonb(p_limite_usuarios));
 return jsonb_build_object('ok',true);
end;$function$

CREATE OR REPLACE FUNCTION docworks_private.provisionar_prueba(p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u auth.users; v_id uuid; v_plan uuid; v_nombre text; v_inmobiliaria text;
begin
  select * into u from auth.users where id=p_user_id for update;
  if u.id is null or u.email_confirmed_at is null then return null; end if;
  select inmobiliaria_id into v_id from public.usuarios where id=u.id;
  if found then return v_id; end if;
  if public.fn_es_super_admin(u.id) then return null; end if;
  -- Las invitaciones conservan su inmobiliaria y rol, aunque el alta venga de la landing.
  perform public.fn_provisionar_usuario_por_email(u.email);
  select inmobiliaria_id into v_id from public.usuarios where id=u.id;
  if found then return v_id; end if;
  if coalesce(u.raw_user_meta_data->>'docworks_registro','') not in ('trial_14_v1','trial_month_v1') then return null; end if;
  v_nombre=trim(coalesce(u.raw_user_meta_data->>'nombre',''));
  v_inmobiliaria=trim(coalesce(u.raw_user_meta_data->>'inmobiliaria',''));
  if length(v_nombre) not between 1 and 120 or length(v_inmobiliaria) not between 1 and 160 then
    raise exception 'Completá tu nombre y el nombre de la inmobiliaria';
  end if;
  select id into v_plan from public.planes where codigo='inicial' and activo;
  if v_plan is null then raise exception 'Plan de prueba no disponible'; end if;
  insert into public.inmobiliarias(nombre) values(v_inmobiliaria) returning id into v_id;
  insert into public.usuarios(id,inmobiliaria_id,email,nombre,rol_base,perfil_permisos)
  values(u.id,v_id,lower(trim(u.email)),v_nombre,'dueno','senior');
  insert into public.membresias(inmobiliaria_id,plan_id,estado,fecha_inicio,fecha_renovacion,fecha_vencimiento,es_prueba)
  values(v_id,v_plan,'activa',u.email_confirmed_at,u.email_confirmed_at+interval '1 month',u.email_confirmed_at+interval '1 month',true);
  insert into public.auditoria(inmobiliaria_id,usuario_id,entidad_tipo,entidad_id,accion,valor_nuevo,origen)
  values(v_id,u.id,'inmobiliaria',v_id,'crear',jsonb_build_object('nombre',v_inmobiliaria,'prueba_meses',1,'registro_origen',u.raw_user_meta_data->>'docworks_registro'),'directa');
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION docworks_private.validar_escritura_prueba()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is not null and not public.fn_es_super_admin(auth.uid()) then
    select inmobiliaria_id into v_id from public.usuarios where id=auth.uid();
    if exists(select 1 from public.membresias where inmobiliaria_id=v_id and es_prueba and
      (estado not in ('activa','pendiente') or fecha_vencimiento is null or fecha_vencimiento<=statement_timestamp())) then
      raise exception 'Tu prueba terminó. Elegí un plan para seguir trabajando.';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.fn_admin_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid;
begin
  if not fn_es_admin(auth.uid()) then raise exception 'Solo Admin/Dueño'; end if;
  v_inmob := fn_mi_inmobiliaria();
  return (select jsonb_build_object(
    'inmobiliaria_nombre', i.nombre,
    'plan_nombre', pl.nombre, 'limite_usuarios', public.fn_limite_usuarios(m.inmobiliaria_id),
    'usuarios_activos', fn_usuarios_activos_count(v_inmob),
    'estado_membresia', m.estado, 'fecha_renovacion', m.fecha_renovacion, 'fecha_vencimiento', m.fecha_vencimiento
  ) from inmobiliarias i join membresias m on m.inmobiliaria_id = i.id join planes pl on pl.id = m.plan_id
  where i.id = v_inmob);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_autoprovisionar_usuario_actual()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_email text; v_id uuid;
begin
  if auth.uid() is null then return null; end if;
  select lower(trim(email)) into v_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
  if v_email is null then return null; end if;
  v_id=public.fn_provisionar_usuario_por_email(v_email);
  if v_id is null then
    perform docworks_private.provisionar_prueba(auth.uid());
    select id into v_id from public.usuarios where id=auth.uid();
  end if;
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.fn_bloque_crear(p_plantilla_id uuid, p_bloque_ref text, p_titulo text, p_contenido text, p_orden integer, p_sin_titulo boolean DEFAULT false, p_condicion text DEFAULT NULL::text, p_obligatoria boolean DEFAULT false, p_proteccion proteccion_t DEFAULT 'C'::proteccion_t)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid; v_id uuid;
begin
  if not fn_es_admin(auth.uid()) then raise exception 'Solo Admin/Dueño puede agregar bloques'; end if;
  select inmobiliaria_id into v_inmob from plantillas where id = p_plantilla_id;
  if v_inmob is null or v_inmob <> fn_mi_inmobiliaria() then
    raise exception 'La plantilla no existe o no pertenece a tu inmobiliaria';
  end if;
  if p_bloque_ref is null or trim(p_bloque_ref) = '' then
    raise exception 'bloque_ref no puede estar vacío';
  end if;
  insert into bloques(plantilla_id, bloque_ref, orden, titulo, sin_titulo, contenido, condicion, activo, obligatoria, proteccion)
  values (p_plantilla_id, p_bloque_ref, p_orden, coalesce(p_titulo,''), p_sin_titulo, coalesce(p_contenido,''), p_condicion, true, p_obligatoria, p_proteccion)
  returning id into v_id;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'bloque', v_id, 'crear',
    jsonb_build_object('plantilla_id',p_plantilla_id,'bloque_ref',p_bloque_ref,'titulo',p_titulo,'orden',p_orden,'proteccion',p_proteccion,'obligatoria',p_obligatoria), 'directa');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_bloque_mover(p_bloque_id uuid, p_nuevo_orden integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid; v_orden_anterior int;
begin
  v_inmob := fn_entidad_inmobiliaria('bloque', p_bloque_id);
  if v_inmob is null or v_inmob <> fn_mi_inmobiliaria() or not fn_es_admin(auth.uid()) then
    raise exception 'No autorizado';
  end if;
  select orden into v_orden_anterior from bloques where id = p_bloque_id;
  update bloques set orden = p_nuevo_orden, actualizado_en = now() where id = p_bloque_id;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_anterior, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'bloque', p_bloque_id, 'mover', jsonb_build_object('orden',v_orden_anterior), jsonb_build_object('orden',p_nuevo_orden), 'directa');
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_clausula_crear(p_titulo text, p_contenido text, p_categoria text DEFAULT 'general'::text, p_tipos jsonb DEFAULT '["todos"]'::jsonb, p_obligatoria boolean DEFAULT false, p_proteccion proteccion_t DEFAULT 'B'::proteccion_t)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid; v_id uuid;
begin
  if not fn_es_admin(auth.uid()) then raise exception 'Solo Admin/Dueño puede crear cláusulas'; end if;
  if p_titulo is null or trim(p_titulo) = '' then raise exception 'El título no puede estar vacío'; end if;
  if p_contenido is null or trim(p_contenido) = '' then raise exception 'El contenido no puede estar vacío'; end if;

  v_inmob := fn_mi_inmobiliaria();
  if v_inmob is null then raise exception 'No se pudo resolver tu inmobiliaria'; end if;

  insert into clausulas(inmobiliaria_id, titulo, categoria, contenido, tipos, obligatoria, proteccion, activo)
  values (v_inmob, p_titulo, coalesce(p_categoria,'general'), p_contenido, coalesce(p_tipos,'["todos"]'::jsonb), p_obligatoria, p_proteccion, true)
  returning id into v_id;

  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'clausula', v_id, 'crear',
    jsonb_build_object('titulo',p_titulo,'categoria',p_categoria,'contenido',p_contenido,'tipos',p_tipos,'obligatoria',p_obligatoria,'proteccion',p_proteccion),
    'directa');

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_configurar_excepcion_broker(p_usuario_id uuid, p_entidad_tipo entidad_t, p_entidad_id uuid, p_accion accion_permiso_t, p_resultado resultado_t, p_motivo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob_admin uuid; v_inmob_broker uuid; v_inmob_entidad uuid; v_rol rol_base_t; v_id uuid;
begin
  if not fn_es_admin(auth.uid()) then raise exception 'Solo Admin/Dueño puede configurar excepciones'; end if;
  v_inmob_admin := fn_mi_inmobiliaria();
  select inmobiliaria_id, rol_base into v_inmob_broker, v_rol from usuarios where id = p_usuario_id and activo;
  if v_rol is distinct from 'broker' then raise exception 'Las excepciones son exclusivas para usuarios con rol broker'; end if;
  v_inmob_entidad := fn_entidad_inmobiliaria(p_entidad_tipo, p_entidad_id);
  if v_inmob_broker is distinct from v_inmob_admin or v_inmob_entidad is distinct from v_inmob_admin then
    raise exception 'El broker o la entidad no pertenecen a tu inmobiliaria';
  end if;

  insert into permisos_broker(usuario_id, entidad_tipo, entidad_id, accion, resultado, motivo, otorgado_por)
  values (p_usuario_id, p_entidad_tipo, p_entidad_id, p_accion, p_resultado, p_motivo, auth.uid())
  on conflict (usuario_id, entidad_tipo, entidad_id, accion)
  do update set resultado = excluded.resultado, motivo = excluded.motivo, otorgado_por = auth.uid(), otorgado_en = now()
  returning id into v_id;

  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_nuevo, origen)
  values (v_inmob_admin, auth.uid(), p_entidad_tipo::text, p_entidad_id, 'configurar_excepcion',
          jsonb_build_object('broker',p_usuario_id,'accion',p_accion,'resultado',p_resultado,'motivo',p_motivo), 'directa');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_invitacion_cancelar(p_invitacion_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid;
begin
  if not fn_es_admin(auth.uid()) then raise exception 'Solo Admin/Dueño puede cancelar invitaciones'; end if;
  v_inmob := fn_mi_inmobiliaria();
  if not exists (select 1 from invitaciones where id = p_invitacion_id and inmobiliaria_id = v_inmob and not usada) then
    raise exception 'Invitación no encontrada o ya utilizada';
  end if;
  delete from invitaciones where id = p_invitacion_id and inmobiliaria_id = v_inmob;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, origen)
  values (v_inmob, auth.uid(), 'invitacion', p_invitacion_id, 'cancelar', 'directa');
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_invitar_usuario(p_email text, p_rol_base rol_base_t, p_perfil_permisos perfil_permisos_t)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid; v_inmob uuid; v_email text; v_limite int; v_usados int;
begin
  if not fn_es_admin(auth.uid()) then raise exception 'Solo Admin/Dueño puede invitar usuarios'; end if;
  v_inmob := fn_mi_inmobiliaria();

  v_limite := fn_limite_usuarios(v_inmob);
  v_usados := fn_usuarios_activos_count(v_inmob) + fn_invitaciones_pendientes_count(v_inmob);
  if v_limite is not null and v_usados >= v_limite then
    raise exception 'Alcanzaste el límite de usuarios de tu plan. Para agregar más usuarios, actualizá tu plan.';
  end if;

  v_email := lower(trim(p_email));
  insert into invitaciones(inmobiliaria_id, email, rol_base, perfil_permisos, invitado_por)
  values (v_inmob, v_email, p_rol_base, p_perfil_permisos, auth.uid())
  returning id into v_id;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'invitacion', v_id, 'crear', jsonb_build_object('email',v_email,'rol',p_rol_base), 'directa');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_mi_contexto()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_es_super boolean;
  v_usuario  usuarios;
  v_inmob    inmobiliarias;
  v_mem      jsonb;
  v_habilitado boolean;
begin
  v_es_super := fn_es_super_admin(auth.uid());
  if v_es_super then
    return jsonb_build_object('es_super_admin', true, 'usuario', null, 'inmobiliaria', null, 'membresia', null, 'habilitado', true);
  end if;

  select * into v_usuario from usuarios where id = auth.uid() and activo;
  if v_usuario.id is null then
    return jsonb_build_object('es_super_admin', false, 'usuario', null, 'inmobiliaria', null, 'membresia', null, 'habilitado', false);
  end if;

  select * into v_inmob from inmobiliarias where id = v_usuario.inmobiliaria_id;

  select jsonb_build_object(
    'plan_codigo', pl.codigo, 'plan_nombre', pl.nombre,
    'limite_usuarios', public.fn_limite_usuarios(m.inmobiliaria_id),
    'usuarios_activos', fn_usuarios_activos_count(v_usuario.inmobiliaria_id),
    'estado', case when m.es_prueba and m.fecha_vencimiento<=now() and m.estado in ('activa','pendiente') then 'vencida' else m.estado::text end, 'es_prueba', m.es_prueba, 'fecha_inicio', m.fecha_inicio,
    'fecha_renovacion', m.fecha_renovacion, 'fecha_vencimiento', m.fecha_vencimiento
  ), (m.estado = 'activa' or m.estado = 'pendiente') and (not m.es_prueba or m.fecha_vencimiento > now())
  into v_mem, v_habilitado
  from membresias m join planes pl on pl.id = m.plan_id
  where m.inmobiliaria_id = v_usuario.inmobiliaria_id;

  return jsonb_build_object(
    'es_super_admin', false,
    'usuario', jsonb_build_object('id', v_usuario.id, 'nombre', v_usuario.nombre, 'email', v_usuario.email, 'rol_base', v_usuario.rol_base, 'perfil_permisos', v_usuario.perfil_permisos),
    'inmobiliaria', jsonb_build_object('id', v_inmob.id, 'nombre', v_inmob.nombre),
    'membresia', v_mem,
    'habilitado', coalesce(v_habilitado, false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_operacion_eliminar_permanente(p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_inmob uuid;
begin
  perform docworks_private.exigir_escritura_operacion('eliminar_permanente',p_id,'{}'::jsonb);
  if not fn_es_admin(auth.uid()) then
    raise exception 'Solo Admin/Dueño puede eliminar operaciones permanentemente';
  end if;

  v_inmob := fn_mi_inmobiliaria();
  if v_inmob is null then
    raise exception 'No se pudo resolver tu inmobiliaria';
  end if;

  delete from operaciones
   where id = p_id
     and inmobiliaria_id = v_inmob
     and eliminado_en is not null;

  if not found then
    raise exception 'La operación no existe, no pertenece a tu inmobiliaria o no está en la papelera';
  end if;
end;
$function$

