  end if;
  if p_nombre is null or trim(p_nombre) = '' then
    raise exception 'El nombre de la plantilla no puede estar vacío';
  end if;
  v_inmob := fn_mi_inmobiliaria();
  insert into plantillas(inmobiliaria_id, tipo_documento, nombre) values (v_inmob, p_tipo_documento, trim(p_nombre)) returning id into v_id;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'plantilla', v_id, 'crear', jsonb_build_object('tipo_documento',p_tipo_documento,'nombre',p_nombre), 'directa');
  return v_id;
end;
$function$

