CREATE OR REPLACE FUNCTION public.fn_resolver_solicitud(p_solicitud_id uuid, p_estado solicitud_estado_t, p_motivo_rechazo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s solicitudes_autorizacion;
  v_inmob_entidad uuid;
  v_actual_text text;
  v_actual_bool boolean;
begin
  if p_estado not in ('aprobada','rechazada') then raise exception 'Estado inválido'; end if;
  select * into s from solicitudes_autorizacion where id = p_solicitud_id for update;
  if s.id is null then raise exception 'Solicitud inexistente'; end if;
  if s.estado <> 'pendiente' then raise exception 'La solicitud ya fue procesada (estado: %)', s.estado; end if;
  if s.inmobiliaria_id is distinct from fn_mi_inmobiliaria() or not fn_es_admin(auth.uid()) then
    raise exception 'No autorizado';
  end if;
  if s.campo <> all(fn_campos_permitidos(s.accion)) then
    raise exception 'Inconsistencia: campo "%" no corresponde a la acción "%"', s.campo, s.accion;
  end if;

  if p_estado = 'aprobada' then
    v_inmob_entidad := fn_entidad_inmobiliaria(s.entidad_tipo, s.entidad_id);
    if v_inmob_entidad is null then raise exception 'La entidad ya no existe'; end if;
    if v_inmob_entidad <> s.inmobiliaria_id then raise exception 'La entidad ya no pertenece a esta inmobiliaria'; end if;

    if s.campo <> 'activo' then
      if s.entidad_tipo = 'bloque' then
        if not (select activo from bloques where id = s.entidad_id) then
          raise exception 'La entidad fue desactivada desde que se creó la solicitud — rechazá y evaluá si corresponde reactivarla primero';
        end if;
      else
        if not (select activo from clausulas where id = s.entidad_id) then
          raise exception 'La entidad fue desactivada desde que se creó la solicitud — rechazá y evaluá si corresponde reactivarla primero';
        end if;
      end if;
    end if;

    if s.entidad_tipo = 'bloque' then
      if s.campo = 'titulo' then
        select titulo into v_actual_text from bloques where id = s.entidad_id;
        if v_actual_text is distinct from s.valor_anterior then
          raise exception 'El valor cambió desde que se creó la solicitud — rechazá y pedí que la regeneren';
        end if;
        update bloques set titulo = s.valor_propuesto, actualizado_en = now() where id = s.entidad_id;
      elsif s.campo = 'contenido' then
        select contenido into v_actual_text from bloques where id = s.entidad_id;
        if v_actual_text is distinct from s.valor_anterior then
          raise exception 'El valor cambió desde que se creó la solicitud — rechazá y pedí que la regeneren';
        end if;
        update bloques set contenido = s.valor_propuesto, actualizado_en = now() where id = s.entidad_id;
      elsif s.campo = 'activo' then
        select activo into v_actual_bool from bloques where id = s.entidad_id;
        if v_actual_bool is distinct from s.valor_anterior::boolean then
          raise exception 'El valor cambió desde que se creó la solicitud — rechazá y pedí que la regeneren';
        end if;
        update bloques set activo = s.valor_propuesto::boolean, actualizado_en = now() where id = s.entidad_id;
      else
        raise exception 'Campo no soportado para bloque: %', s.campo;
      end if;
    else
      if s.campo = 'titulo' then
        select titulo into v_actual_text from clausulas where id = s.entidad_id;
        if v_actual_text is distinct from s.valor_anterior then
          raise exception 'El valor cambió desde que se creó la solicitud — rechazá y pedí que la regeneren';
        end if;
        update clausulas set titulo = s.valor_propuesto, actualizada_en = now() where id = s.entidad_id;
      elsif s.campo = 'contenido' then
        select contenido into v_actual_text from clausulas where id = s.entidad_id;
        if v_actual_text is distinct from s.valor_anterior then
          raise exception 'El valor cambió desde que se creó la solicitud — rechazá y pedí que la regeneren';
        end if;
        update clausulas set contenido = s.valor_propuesto, actualizada_en = now() where id = s.entidad_id;
      elsif s.campo = 'activo' then
        select activo into v_actual_bool from clausulas where id = s.entidad_id;
        if v_actual_bool is distinct from s.valor_anterior::boolean then
          raise exception 'El valor cambió desde que se creó la solicitud — rechazá y pedí que la regeneren';
        end if;
        update clausulas set activo = s.valor_propuesto::boolean, actualizada_en = now() where id = s.entidad_id;
      else
        raise exception 'Campo no soportado para cláusula: %', s.campo;
      end if;
    end if;

    insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_anterior, valor_nuevo, origen, solicitud_id, autorizado_por)
    values (s.inmobiliaria_id, s.usuario_id, s.entidad_tipo::text, s.entidad_id, s.accion::text,
            jsonb_build_object(s.campo, s.valor_anterior), jsonb_build_object(s.campo, s.valor_propuesto),
            'autorizacion', s.id, auth.uid());
  end if;

  update solicitudes_autorizacion
     set estado = p_estado, resuelta_por = auth.uid(), resuelta_en = now(),
         motivo_rechazo = case when p_estado='rechazada' then p_motivo_rechazo else null end
   where id = p_solicitud_id;
end;
$function$

