CREATE OR REPLACE FUNCTION public.fn_bloque_mover(p_bloque_id uuid, p_nuevo_orden integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid; v_orden_anterior int;
begin
  v_inmob := fn_entidad_inmobiliaria('bloque', p_bloque_id);
  if v_inmob is null or v_inmob <> fn_mi_inmobiliaria() or not fn_es_admin(auth.uid()) then
    raise exception 'No autorizado';
  end if;
  select orden into v_orden_anterior from bloques where id = p_bloque_id;
  update bloques set orden = p_nuevo_orden, actualizado_en = now() where id = p_bloque_id;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_anterior, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'bloque', p_bloque_id, 'mover', jsonb_build_object('orden',v_orden_anterior), jsonb_build_object('orden',p_nuevo_orden), 'directa');
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_clausula_editar(p_clausula_id uuid, p_titulo text, p_contenido text, p_categoria text DEFAULT NULL::text, p_tipos jsonb DEFAULT NULL::jsonb, p_obligatoria boolean DEFAULT NULL::boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_permiso resultado_t; v_anterior jsonb; v_inmob uuid;
begin
  v_inmob := fn_entidad_inmobiliaria('clausula', p_clausula_id);
  if v_inmob is null or v_inmob <> fn_mi_inmobiliaria() then
    raise exception 'La cláusula no existe o no pertenece a tu inmobiliaria';
  end if;
  v_permiso := fn_permiso_efectivo(auth.uid(), 'clausula', p_clausula_id, 'editar');
  if v_permiso <> 'permitido' then raise exception 'No tenés permiso para editar esta cláusula (resultado: %)', v_permiso; end if;
  select to_jsonb(c) into v_anterior from clausulas c where c.id = p_clausula_id;
  update clausulas set
    titulo = p_titulo, contenido = p_contenido,
    categoria = coalesce(p_categoria, categoria),
    tipos = coalesce(p_tipos, tipos),
    obligatoria = coalesce(p_obligatoria, obligatoria),
    actualizada_en = now()
  where id = p_clausula_id;
  insert into auditoria(inmobiliaria_id, usuario_id, entidad_tipo, entidad_id, accion, valor_anterior, valor_nuevo, origen)
  values (v_inmob, auth.uid(), 'clausula', p_clausula_id, 'editar', v_anterior, jsonb_build_object('titulo',p_titulo,'contenido',p_contenido), 'directa');
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_clausula_eliminar(p_clausula_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_permiso public.resultado_t; v_anterior jsonb; v_inmob uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Debés iniciar sesión'; END IF;
 v_inmob:=public.fn_entidad_inmobiliaria('clausula',p_clausula_id);
 IF v_inmob IS NULL OR v_inmob<>public.fn_mi_inmobiliaria() THEN RAISE EXCEPTION 'La cláusula no existe o no pertenece a tu inmobiliaria'; END IF;
 v_permiso:=public.fn_permiso_efectivo(auth.uid(),'clausula',p_clausula_id,'eliminar');
 IF v_permiso<>'permitido' THEN RAISE EXCEPTION 'No tenés permiso para eliminar esta cláusula (resultado: %)',v_permiso; END IF;
 SELECT to_jsonb(c) INTO v_anterior FROM public.clausulas c WHERE c.id=p_clausula_id FOR UPDATE;
 IF (v_anterior->>'activo')::boolean IS FALSE THEN RETURN; END IF;
 UPDATE public.clausulas SET activo=false,eliminado_en=now(),actualizada_en=now() WHERE id=p_clausula_id AND inmobiliaria_id=v_inmob;
 INSERT INTO public.auditoria(inmobiliaria_id,usuario_id,entidad_tipo,entidad_id,accion,valor_anterior,valor_nuevo,origen) VALUES(v_inmob,auth.uid(),'clausula',p_clausula_id,'eliminar',v_anterior,jsonb_build_object('activo',false,'eliminado_en',now()),'directa');
END;$function$

CREATE OR REPLACE FUNCTION public.fn_permiso_efectivo(p_usuario_id uuid, p_entidad_tipo entidad_t, p_entidad_id uuid, p_accion accion_permiso_t)
 RETURNS resultado_t
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_inmob_usuario uuid;
  v_inmob_entidad uuid;
  v_rol           rol_base_t;
  v_excepcion     resultado_t;
  v_proteccion    proteccion_t;
  v_perfil        perfil_permisos_t;
begin
  if p_usuario_id <> auth.uid() and not fn_es_admin(auth.uid()) then
    return 'denegado';
  end if;

  select inmobiliaria_id, rol_base into v_inmob_usuario, v_rol from usuarios where id = p_usuario_id and activo;
  if v_inmob_usuario is null then
    return 'denegado';
  end if;

  v_inmob_entidad := fn_entidad_inmobiliaria(p_entidad_tipo, p_entidad_id);
  if v_inmob_entidad is null or v_inmob_entidad <> v_inmob_usuario then
    return 'denegado';
  end if;

  if v_rol in ('dueno','admin') then
    return 'permitido';
  end if;

  if v_rol <> 'broker' then
    return 'denegado';
  end if;

  if p_entidad_tipo = 'bloque' then
    select proteccion into v_proteccion from bloques where id = p_entidad_id;
  else
    select proteccion into v_proteccion from clausulas where id = p_entidad_id;
  end if;

  select resultado into v_excepcion
    from permisos_broker
   where usuario_id = p_usuario_id and entidad_tipo = p_entidad_tipo
     and entidad_id = p_entidad_id and accion = p_accion;
  if v_excepcion is not null then
    return v_excepcion;
  end if;

  if v_proteccion = 'C' then
    return 'denegado';
  elsif v_proteccion = 'B' then
    return 'permitido';
  elsif v_proteccion = 'A' then
    select perfil_permisos into v_perfil from usuarios where id = p_usuario_id;
    return case when v_perfil = 'senior' then 'permitido' else 'requiere_autorizacion' end;
  end if;

  return 'permitido';
end;
$function$
